const INPUT: usize=48;
fn mul(mut a:u8,mut b:u8)->u8{let mut r=0;while b!=0{if b&1!=0{r^=a;}a=(a<<1)^if a&128!=0{0x1b}else{0};b>>=1;}r}
fn pow(mut a:u8,mut n:u32)->u8{let mut r=1;while n!=0{if n&1!=0{r=mul(r,a);}a=mul(a,a);n>>=1;}r}
fn decrypt(key:&[u8],input:&[u8])->[u8;16]{let mut s=[0u8;256];let mut inv=[0u8;256];for x in 0..256{let q=if x==0{0}else{pow(x as u8,254)};s[x]=q^q.rotate_left(1)^q.rotate_left(2)^q.rotate_left(3)^q.rotate_left(4)^0x63;}for x in 0..256{inv[s[x] as usize]=x as u8;}let rc=[1u8,2,4,8,16,32,64];let mut rk=[0u8;240];rk[..32].copy_from_slice(key);let mut w=32;while w<240{let wi=w/4;let mut t=[rk[w-4],rk[w-3],rk[w-2],rk[w-1]];if wi%8==0{t.rotate_left(1);for x in &mut t{*x=s[*x as usize];}t[0]^=rc[wi/8-1];}else if wi%8==4{for x in &mut t{*x=s[*x as usize];}}for j in 0..4{rk[w]=rk[w-32]^t[j];w+=1;}}
 let mut st=[0u8;16];for i in 0..16{st[i]=input[i]^rk[224+i];}for round in (1..14).rev(){let p=st;for c in 0..4{for r in 0..4{st[r+4*c]=inv[p[r+4*((c+4-r)%4)] as usize];}}for i in 0..16{st[i]^=rk[round*16+i];}for c in 0..4{let o=4*c;let [a,b,d,e]=[st[o],st[o+1],st[o+2],st[o+3]];st[o]=mul(a,14)^mul(b,11)^mul(d,13)^mul(e,9);st[o+1]=mul(a,9)^mul(b,14)^mul(d,11)^mul(e,13);st[o+2]=mul(a,13)^mul(b,9)^mul(d,14)^mul(e,11);st[o+3]=mul(a,11)^mul(b,13)^mul(d,9)^mul(e,14);}}
 let p=st;for c in 0..4{for r in 0..4{st[r+4*c]=inv[p[r+4*((c+4-r)%4)] as usize];}}for i in 0..16{st[i]^=rk[i];}st}
#[no_mangle]
pub unsafe extern "C" fn cbench_security_rijndael_decrypt(values:*const i64,length:usize,output:*mut u8,capacity:usize)->i64{if values.is_null()||length!=INPUT{return -1;}let v=unsafe{std::slice::from_raw_parts(values,length)};if v.iter().any(|&x|!(0..=255).contains(&x)){return -1;}if output.is_null()||capacity<16{return -2;}let key:Vec<u8>=v[..32].iter().map(|&x|x as u8).collect();let block:Vec<u8>=v[32..].iter().map(|&x|x as u8).collect();let plain=decrypt(&key,&block);unsafe{std::slice::from_raw_parts_mut(output,16).copy_from_slice(&plain);}16}
